INSERT bi.MovimientoReferencia(Clave,IdLote,IdProducto,Fecha,Tipo,Cantidad,IdOperacion) SELECT N'BIM2-venta-10-020-12',@lote,12,N'2026-10-02 15:00:00',N'Salida',8,IdOperacion FROM bi.OperacionReferencia WHERE Clave=N'BIM2-venta-10-020';
IF (SELECT COUNT(*) FROM bi.OperacionReferencia WHERE IdLote=@lote)<>627 OR (SELECT COUNT(*) FROM bi.DetalleReferencia d JOIN bi.OperacionReferencia o ON o.IdOperacion=d.IdOperacion WHERE o.IdLote=@lote)<>1240 THROW 51000,N'Volumen inesperado.',1;
IF EXISTS(SELECT 1 FROM bi.OperacionReferencia o OUTER APPLY(SELECT SUM(Importe) Importe FROM bi.DetalleReferencia d WHERE d.IdOperacion=o.IdOperacion)x WHERE o.IdLote=@lote AND (o.Total<>x.Importe OR o.Total<>o.Base+o.Igv OR o.Fecha<'20260401' OR o.Fecha>='20261013')) THROW 51000,N'Importes o fechas inconsistentes.',1;
IF EXISTS(SELECT 1 FROM bi.OperacionReferencia o WHERE o.IdLote=@lote AND ((o.IdCliente IS NOT NULL AND NOT EXISTS(SELECT 1 FROM bi.EntidadReferencia e WHERE e.IdEntidad=o.IdCliente AND e.Tipo='cliente' AND e.IdLote=@lote)) OR (o.IdProveedor IS NOT NULL AND NOT EXISTS(SELECT 1 FROM bi.EntidadReferencia e WHERE e.IdEntidad=o.IdProveedor AND e.Tipo='proveedor' AND e.IdLote=@lote)))) THROW 51000,N'Tercero inválido.',1;
IF EXISTS(SELECT 1 FROM (SELECT SUM(CAST(CASE WHEN Tipo='Salida' THEN -Cantidad ELSE Cantidad END AS bigint)) OVER(PARTITION BY IdProducto ORDER BY Fecha,IdMovimiento ROWS UNBOUNDED PRECEDING) Saldo FROM bi.MovimientoReferencia WHERE IdLote=@lote) s WHERE Saldo<0) THROW 51000,N'Saldo negativo de referencia.',1;
UPDATE bi.LoteReferencia SET Estado='Completo' WHERE IdLote=@lote; COMMIT;